package dll

import (
	"testing"
)

func TestPushBackToSlice(t *testing.T) {
	l := New[int]()
	l.PushBack(1)
	l.PushBack(2)
	l.PushBack(3)
	got := l.ToSlice()
	want := []int{1, 2, 3}
	for i, v := range want {
		if got[i] != v {
			t.Fatalf("want %v got %v", want, got)
		}
	}
}

func TestPushFrontToSlice(t *testing.T) {
	l := New[int]()
	l.PushFront(1)
	l.PushFront(2)
	l.PushFront(3)
	got := l.ToSlice()
	want := []int{3, 2, 1}
	for i, v := range want {
		if got[i] != v {
			t.Fatalf("want %v got %v", want, got)
		}
	}
}

func TestPopFront(t *testing.T) {
	l := New[string]()
	l.PushBack("a")
	l.PushBack("b")
	v, ok := l.PopFront()
	if !ok || v != "a" {
		t.Fatalf("want a,true got %v,%v", v, ok)
	}
	if l.Len() != 1 {
		t.Fatalf("want len 1")
	}
}

func TestPopBack(t *testing.T) {
	l := New[string]()
	l.PushBack("x")
	l.PushBack("y")
	v, ok := l.PopBack()
	if !ok || v != "y" {
		t.Fatalf("want y,true got %v,%v", v, ok)
	}
}

func TestPopEmpty(t *testing.T) {
	l := New[int]()
	_, ok := l.PopFront()
	if ok {
		t.Fatal("PopFront on empty should return false")
	}
	_, ok = l.PopBack()
	if ok {
		t.Fatal("PopBack on empty should return false")
	}
}

